{
  "items": [
    {
      "path": "tools.team_tasks_list",
      "description": "View the shared team task board. Use this to check task status, not to wait for teammates. Teammates will message you when done.",
      "signature": "tools.team_tasks_list(): Promise<string | null>"
    },
    {
      "path": "tools.team_status",
      "description": "View team members with their current status, agent type, and session IDs. Use this to check who is working, idle, or shut down. Includes a task summary.",
      "signature": "tools.team_status(): Promise<string | null>"
    },
    {
      "path": "tools.team_message",
      "description": "Send a message to a specific teammate or to the lead. Use 'lead' to message the team lead. Lead only: pass 'model' (provider/model) to update a teammate's model in-place.",
      "signature": "tools.team_message({
  /** Recipient name ('lead' or teammate name) */
  to: string,
  /** Message content (max 10KB). Optional only when 'model' is provided. */
  text?: string,
  /** Approve a teammate's plan (only when recipient has plan_approval='pending'). @default false */
  approve?: boolean,
  /** Reject a teammate's plan with reason (only when recipient has plan_approval='pending') */
  reject?: string,
  /** Lead only. Re-activate a teammate who already reported task completion. @default false */
  force?: boolean,
  /** Lead only: update the recipient teammate's model in-place, in 'provider/model' format. */
  model?: string,
  /**
   * Lead only, to=lead: update the shared worker budget without interrupting running work. Text is optional for scheduling updates.
   * @integer @minimum 0
   */
  max_running_members?: number,
  /**
   * Lead only, to=lead: persist provider preference locally for this mission. Empty array restores default routing. Separate call from other controls; text optional.
   * @maxItems 64
   */
  provider_order?: Array<string>,
  /** Revision read from team_status; rejects stale provider-order edits. @integer @minimum 0 */
  provider_order_revision?: number,
  /**
   * Durable model/effort preference. Balanced mode uses a shrinking quality window and weighted distribution; reserve models run only when ordinary candidates are insufficient. Separate lead-only update; null restores project inheritance.
   */
  model_policy?: {
      mode: "legacy" | "balanced",
      /**
       * Cost tie-break basis; effective costs never fall back to API benchmarks or estimates. Amortized uses explicit subscription-allocated AA task estimates, not measured billing.
       */
      costMode?: "legacy" | "benchmark" | "effective" | "amortized",
      /** @minimum 0 @maximum 10 */
      maxIntelligenceGap: number,
      /** @maxItems 128 */
      models: Array<{
          /** Exact evaluated provider/model ID */
          id: string,
          /** Exact evaluated native reasoning variant; omitted means default */
          reasoningEffort?: string,
          /** Independent traffic weight; zero excludes automatic selection. @integer @minimum 0 @maximum 100 */
          preference?: number,
          enabled?: boolean,
          reserve?: boolean,
        }>,
    } | null,
  /** Model policy revision read from team_status; rejects stale edits. @integer @minimum 0 */
  model_policy_revision?: number,
  /** Lead only, to=lead: enable or disable deterministic assignment. */
  auto_dispatch?: boolean,
  /** Lead only, to=lead: enable or disable automatic worker creation. */
  auto_scale?: boolean,
  /** Frozen mission classification defaults/explicit overrides */
  classification?: {
    mode?: "off" | "auto" | "jev" | "general" | "x86",
    /** Explicit helper model in provider/model format; no model is chosen implicitly */
    helperModel?: string,
    /** Native reasoning variant for the helper model */
    helperVariant?: string,
    /** Exact classifier tool ID; empty means discover the known JEV contract */
    toolId?: string,
    /** @integer @minimum 1 */
    timeoutMs?: number,
    missionMode?: "supervised" | "long_run",
    /** Explicit model for embedded general classification; never activated automatically */
    generalModel?: string,
    /** Reasoning variant for the general classifier */
    generalVariant?: string,
    /** In auto mode, prefer the discovered x86 tool for explicit x86 tasks */
    specialized?: boolean,
    /** Exact specialized tool ID; empty discovers the known classify_x86 contract */
    x86ToolId?: string,
    /** @maxItems 8 */
    fallbacks?: Array<{
        method: "jev" | "general",
        /** Explicitly authorized classifier/helper model */
        model: string,
        /** Reasoning variant */
        variant?: string,
        /** Exact JEV tool ID */
        toolId?: string,
      }>,
    limits?: {
      /** @integer @minimum 0 */
      retries?: number,
      /** @integer @minimum 0 */
      retryDelayMs?: number,
      /** @integer @minimum 1 */
      maxAttempts?: number,
      /** @integer @minimum 1 */
      maxCalls?: number,
      /** @integer @minimum 1 */
      maxDurationMs?: number,
      /** @integer @minimum 1 */
      maxInputBytes?: number,
      /** @integer @minimum 1 */
      concurrency?: number,
      /** @integer @minimum 1 */
      circuitThreshold?: number,
      /** @integer @minimum 1 */
      circuitCooldownMs?: number,
      /** @integer @minimum 0 */
      maxCircuitRechecks?: number,
    },
  },
}): Promise<string | null>"
    },
    {
      "path": "tools.team_spawn",
      "description": "Spawn a new teammate that works in parallel. The teammate starts immediately with the given prompt. Each teammate gets their own git worktree for file isolation. Teammates work asynchronously and will message you when done. Do not poll for their status. Context is fresh by default; opt into fork/checkpoint/compact_fork to inherit a team's session history. Lead only.",
      "signature": "tools.team_spawn({
  /** Teammate name (lowercase alphanumeric with hyphens) */
  name: string,
  /** Agent type (e.g. 'build', 'plan', 'explore') */
  agent?: string,
  /** Task instructions for the teammate */
  prompt: string,
  /** Model in provider/model format (optional, uses default) */
  model?: string,
  /** Native reasoning variant for an explicit/configured model; routed models use the catalogue effort */
  variant?: string,
  /** Task complexity for deterministic model routing; overrides claim_task. @integer @minimum 0 @maximum 100 */
  complexity?: number,
  /** Task risk for deterministic model routing only; overrides claim_task. @integer @minimum 0 @maximum 100 */
  risk?: number,
  /** Task ID to auto-claim for this teammate (optional) */
  claim_task?: string,
  /** Create a git worktree for file isolation (default: true, set false for read-only agents). @default true */
  worktree?: boolean,
  /** Require teammate to send a plan for approval before writing files (default: false). @default false */
  plan_approval?: boolean,
  /** Opt-in V2 history inheritance; independent reviewers should use fresh. */
  context?: {
    mode: "fresh" | "fork" | "checkpoint" | "compact_fork",
    /**
     * current (default), lead, or a member name/session ID in this team; compact_fork requires a distinct idle source
     */
    from?: string,
    /** checkpoint only: exclusive native boundary; this message and later messages are excluded */
    messageID?: string,
  },
}): Promise<string | null>"
    },
    {
      "path": "tools.team_tasks_add",
      "description": "Add tasks with optional durable fresh/fork/checkpoint decisions. Lead can update queued context decisions using tasks:[] and context_updates; require_context prevents undecided tasks from dispatching.",
      "signature": "tools.team_tasks_add({
  /** Tasks to add */
  tasks: Array<{
      /** Task description */
      content: string,
      /** Task priority. @default "medium" */
      priority?: "high" | "medium" | "low",
      /** Task IDs this depends on */
      depends_on?: Array<string>,
      /** Agent type affinity for auto-dispatch (e.g. build). Omit for any member. */
      agent?: string,
      /** Task complexity for deterministic model routing. @integer @minimum 0 @maximum 100 */
      complexity?: number,
      /** Task risk for model routing only (not review policy). @integer @minimum 0 @maximum 100 */
      risk?: number,
      /** Explicit task kind supplied to the fixed classification protocol */
      task_type?: string,
      /** Task-specific classification data, treated as data rather than instructions */
      classification_input?: {},
      context?: {
        mode: "fresh" | "fork" | "checkpoint" | "compact_fork" | "pending",
        /** Source member/session, current or lead; bound to a native identity when saved */
        from?: string,
        /** Exclusive native checkpoint boundary; only for checkpoint */
        messageID?: string,
        /** Pipeline decision and evidence; pending blocks admission until resolved. @minLength 1 @maxLength 4000 */
        reason: string,
        /** Explicit directory policy; false shares the mission directory, true requests an isolated worktree */
        worktree?: boolean,
      },
    }>,
  /** Lead only; separate call with tasks: []. Atomic revision-checked updates to unassigned pending/blocked tasks. */
  context_updates?: Array<{
      /** Existing task ID */
      task_id: string,
      /** @integer @minimum 0 */
      revision: number,
      context: {
        mode: "fresh" | "fork" | "checkpoint" | "compact_fork" | "pending",
        /** Source member/session, current or lead; bound to a native identity when saved */
        from?: string,
        /** Exclusive native checkpoint boundary; only for checkpoint */
        messageID?: string,
        /** Pipeline decision and evidence; pending blocks admission until resolved. @minLength 1 @maxLength 4000 */
        reason: string,
        /** Explicit directory policy; false shares the mission directory, true requests an isolated worktree */
        worktree?: boolean,
      },
    }>,
  /** Lead only with tasks: []; require a decided context for every future task admission in this mission */
  require_context?: boolean,
}): Promise<string | null>"
    }
  ],
  "remaining": 42,
  "next": {
    "offset": 5
  }
}
